mapper.select:
SELECT * FROM ai_execution_task
WHERE project_id = #{projectId}
  AND create_user = #{createUser}
  AND idempotency_key = #{idempotencyKey}
LIMIT 1

SELECT ec.*, fc.num AS case_num, fc.name AS case_name FROM ai_execution_case ec LEFT JOIN functional_case fc ON fc.id = ec.case_id WHERE ec.task_id = #{taskId}
AND ec.status IN
#{status}
ORDER BY ec.pos ASC, ec.create_time ASC

SELECT * FROM ai_execution_event
WHERE task_id = #{taskId}
  AND sequence > #{cursor}
ORDER BY sequence ASC
LIMIT #{limit}

mapper.insert:
INSERT INTO ai_execution_case (
    id, task_id, project_id, case_id, test_plan_id, test_plan_case_id, status, result,
    pos, retry_count, error_message, create_time, update_time
) VALUES (
    #{id}, #{taskId}, #{projectId}, #{caseId}, #{testPlanId}, #{testPlanCaseId}, #{status}, #{result},
    #{pos}, #{retryCount}, #{errorMessage}, #{createTime}, #{updateTime}
)

INSERT INTO ai_execution_event (
    id, task_id, case_id, step_id, sequence, event_time, level, event_type, message,
    artifact_ids, sanitized_metadata, create_user
) VALUES (
    #{id}, #{taskId}, #{caseId}, #{stepId}, #{sequence}, #{eventTime}, #{level}, #{eventType}, #{message},
    NULL, #{sanitizedMetadata}, #{createUser}
)

mapper.update:
UPDATE ai_execution_task
SET status = #{status}, update_user = #{updateUser}, update_time = #{updateTime}
WHERE id = #{id}

UPDATE ai_execution_task
SET status = #{status},
    confirm_required = 0,
    update_user = #{updateUser},
    update_time = #{updateTime}
WHERE id = #{id}

UPDATE ai_execution_case
SET status = #{status},
    result = #{result},
    error_message = #{errorMessage},
    update_time = #{updateTime}
WHERE task_id = #{taskId}
  AND case_id = #{caseId}

sql.where:
tp.project_id = #{projectId}
AND tp.type = 'TEST_PLAN'

    AND tp.status != 'ARCHIVED'


    AND tp.status = #{status}


    AND (
        LOWER(tp.id) LIKE CONCAT('%', #{likeKeyword}, '%') ESCAPE '\\'
        OR LOWER(tp.name) LIKE CONCAT('%', #{likeKeyword}, '%') ESCAPE '\\'
        OR CAST(tp.num AS CHAR) LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'
    )
